-- Development Phase 02, Sprint 2 — the reservation engine.
--
-- Generated by drizzle-kit, then edited by hand:
--   * the backfill runs before the new CHECK constraints that depend on it;
--   * foreign keys the TypeScript schema cannot declare (the cashiering schema imports the
--     bookings schema) are appended at the end;
--   * the new booking_action values are the LAST statements. Drizzle applies every pending
--     migration in one transaction, and a value added there cannot be used until it commits, so
--     nothing in any migration may use them.
CREATE TABLE IF NOT EXISTS "reservation_requests" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"idempotency_key" text NOT NULL,
	"request_hash" text NOT NULL,
	"user_id" uuid,
	"response" jsonb,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"completed_at" timestamp with time zone,
	CONSTRAINT "reservation_requests_tenant_key_uq" UNIQUE("tenant_id","idempotency_key")
);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "ledger_account_rates" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"ledger_account_id" uuid NOT NULL,
	"property_id" uuid NOT NULL,
	"room_id" uuid NOT NULL,
	"rate_plan_id" uuid,
	"valid_from" date NOT NULL,
	"valid_to" date NOT NULL,
	"mode" text DEFAULT 'fixed' NOT NULL,
	"value" numeric(12, 2) NOT NULL,
	"active" boolean DEFAULT true NOT NULL,
	"note" text,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "ledger_account_rates_range_valid" CHECK ("ledger_account_rates"."valid_to" >= "ledger_account_rates"."valid_from"),
	CONSTRAINT "ledger_account_rates_mode_valid" CHECK ("ledger_account_rates"."mode" in ('fixed', 'discount_pct')),
	CONSTRAINT "ledger_account_rates_value_valid" CHECK ("ledger_account_rates"."value" >= 0 and ("ledger_account_rates"."mode" <> 'discount_pct' or "ledger_account_rates"."value" <= 100))
);
--> statement-breakpoint
