-- Backfill (hand-written). ---------------------------------------------------------------
--
-- Every existing booking gets a reservation kind that matches what it already does:
-- a Pending booking holds its rooms today and has no release time, so it stays the column's
-- default — an unconfirmed hold that is never released automatically; everything else is a
-- confirmed booking. inventory_held is generated from status and kind, so Cancelled and Rejected
-- bookings come out as not holding without being touched.
UPDATE "bookings" SET "reservation_kind" = 'confirm' WHERE "status" <> 'Pending';
--> statement-breakpoint
UPDATE "bookings" SET "origin" = 'ota' WHERE "source" = 'OTA';
--> statement-breakpoint
-- Every existing night was priced from the rate calendar, so its list price is what was charged.
UPDATE "booking_days" SET "list_selling_price" = "selling_price" WHERE "list_selling_price" IS NULL;
--> statement-breakpoint
-- A service charge belongs to the hotel, not the state: a tax-exempt guest still pays it.
UPDATE "tax_types" SET "exemptible" = false WHERE "name" ~* 'service';
--> statement-breakpoint
-- The group foreign key below would refuse a booking pointing at a group that no longer exists.
UPDATE "bookings" b SET "group_id" = NULL
WHERE b."group_id" IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM "booking_groups" g WHERE g."id" = b."group_id");
--> statement-breakpoint
-- booking_days gains UNIQUE(booking_id, date) below. Bookings only ever write one row per night
-- (amend deletes and re-inserts), so a duplicate here means corrupt data: the migration stops
-- rather than guess which row is right.
DO $$
DECLARE dupes integer;
BEGIN
  SELECT count(*) INTO dupes FROM (
    SELECT 1 FROM "booking_days" GROUP BY "booking_id", "date" HAVING count(*) > 1
  ) d;
  IF dupes > 0 THEN
    RAISE EXCEPTION 'booking_days has % duplicated booking nights; resolve them before migrating', dupes;
  END IF;
END $$;
--> statement-breakpoint
